module shortest_path (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] s,\n    input wire [2:0] t,\n    input wire [7:0] adj_0,\n    input wire [7:0] adj_1,\n    input wire [7:0] adj_2,\n    input wire [7:0] adj_3,\n    input wire [7:0] adj_4,\n    input wire [7:0] adj_5,\n    input wire [7:0] adj_6,\n    input wire [7:0] adj_7,\n    output reg [3:0] result,\n    output reg done,\n    output reg impossible\n);\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] INIT = 2'd1;\n    localparam [1:0] LOOP = 2'd2;\n    localparam [1:0] FINISH = 2'd3;\n    localparam [3:0] MAX_DIST = 4'd15;\n    \n    reg [1:0] state, next_state;\n    reg [3:0] dist_reg [0:7];\n    reg [3:0] next_dist_reg [0:7];\n    reg [2:0] queue [0:7];\n    reg [2:0] next_queue [0:7];\n    reg [2:0] queue_head, next_queue_head;\n    reg [2:0] queue_tail, next_queue_tail;\n    reg [9:0] cycle_count, next_cycle_count;\n    wire [7:0] adj [0:7];\n    integer i;\n    \n    assign adj[0] = adj_0;\n    assign adj[1] = adj_1;\n    assign adj[2] = adj_2;\n    assign adj[3] = adj_3;\n    assign adj[4] = adj_4;\n    assign adj[5] = adj_5;\n    assign adj[6] = adj_6;\n    assign adj[7] = adj_7;\n    \n    always @(*) begin\n        next_state = state;\n        next_queue_head = queue_head;\n        next_queue_tail = queue_tail;\n        next_cycle_count = cycle_count + 10'd1;\n        \n        for (i = 0; i < 8; i = i + 1) begin\n            next_queue[i] = queue[i];\n            next_dist_reg[i] = dist_reg[i];\n        end\n        \n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = INIT;\n                    next_cycle_count = 10'd0;\n                end\n            end\n            \n            INIT: begin\n                next_queue[0] = s;\n                next_queue_head = 3'd0;\n                next_queue_tail = 3'd1;\n                \n                for (i = 0; i < 8; i = i + 1) begin\n                    next_dist_reg[i] = MAX_DIST;\n                end\n                next_dist_reg[s] = 4'd0;\n                \n                if (s == t) begin\n                    next_state = FINISH;\n                end else begin\n                    next_state = LOOP;\n                end\n            end\n            \n            LOOP: begin\n                if (queue_head == queue_tail) begin\n                    next_state = FINISH;\n                end else if (cycle_count >= 10'd1000) begin\n                    next_state = FINISH;\n                end else begin\n                    reg [2:0] current_node = queue[queue_head];\n                    next_queue_head = queue_head + 3'd1;\n                    \n                    if (current_node == t) begin\n                        next_state = FINISH;\n                    end else begin\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if (adj[current_node][i] && dist_reg[i] == MAX_DIST) begin\n                                if (next_queue_tail < 3'd8) begin\n                                    next_queue[next_queue_tail] = i;\n                                    next_queue_tail = next_queue_tail + 3'd1;\n                                    next_dist_reg[i] = dist_reg[current_node] + 4'd1;\n                                end\n                            end\n                        end\n                        next_state = LOOP;\n                    end\n                end\n            end\n            \n            FINISH: begin\n                next_state = state;\n            end\n            \n            default: next_state = IDLE;\n        endcase\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            result <= 4'd0;\n            queue_head <= 3'd0;\n            queue_tail <= 3'd0;\n            cycle_count <= 10'd0;\n            \n            for (i = 0; i < 8; i = i + 1) begin\n                dist_reg[i] <= MAX_DIST;\n                queue[i] <= 3'd0;\n            end\n        end else begin\n            state <= next_state;\n            queue_head <= next_queue_head;\n            queue_tail <= next_queue_tail;\n            cycle_count <= next_cycle_count;\n            \n            for (i = 0; i < 8; i = i + 1) begin\n                dist_reg[i] <= next_dist_reg[i];\n                queue[i] <= next_queue[i];\n            end\n            \n            done <= (next_state == FINISH);\n            impossible <= (next_state == FINISH) && (next_dist_reg[t] == MAX_DIST);\n            result <= (next_state == FINISH) ? next_dist_reg[t] : 4'd0;\n        end\n    end\nendmodule